sealed trait TokenType extends Product with Serializable { def value: String }

object TokenType {
  case object STRING extends TokenType { override val value: String = "string" }
  case object NUMERIC extends TokenType { override val value: String = "numeric" }
  case object TEMPORAL extends TokenType { override val value: String = "temporal" }
  case object STRUCTURED extends TokenType { override val value: String = "structured" }
  case object BINARY extends TokenType { override val value: String = "binary" }
  case object NULL extends TokenType { override val value: String = "null" }

  val values: List[TokenType] = List(STRING, NUMERIC, TEMPORAL, STRUCTURED, BINARY, NULL)

  def fromString(s: String): Option[TokenType] = values.find(_.value == s)
}

final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) extends Serializable {

  def withMetadata(kvs: (String, Any)*): Token =
    if (kvs.isEmpty) this else copy(metadata = metadata ++ kvs.toMap)

  def withMetadata(more: Map[String, Any]): Token =
    if (more.isEmpty) this else copy(metadata = metadata ++ more)
}

