final class TokenContainer[+T](items: Seq[T]) extends Serializable {
  private val all: Vector[T] = items.toVector

  def getAll: Vector[T] = all

  def mapTokens(f: T => String): Vector[String] = all.map(f)
}

final class TokenSink[-T] extends Serializable {
  private val received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val out = received.toList
    received.clear()
    out
  }
}

final class BivariantHandler[T](default: T) extends Serializable {
  private var value: T = default

  def get: T = value

  def set(newValue: T): Unit = value = newValue

  def transform(f: T => T): T = {
    value = f(value)
    value
  }
}

