trait BaseTokenizer[-T] extends Serializable {
  def tokenize(value: T): Token

  def tokenizeBatch(values: IterableOnce[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

final class StringTokenizer(
  encoding: Charset = StandardCharsets.UTF_8,
  normalizer: String => String = identity
) extends BaseTokenizer[Any] {

  def this(encoding: String, normalizer: String => String) =
    this(Charset.forName(encoding), normalizer)

  def this(encoding: String) =
    this(Charset.forName(encoding), identity)

  def tokenize(value: String): Token =
    Token(normalizer(value), TokenType.STRING)

  def tokenize(value: Array[Byte]): Token =
    Token(normalizer(new String(value, encoding)), TokenType.STRING)

  override def tokenize(value: Any): Token = ***REDACTED*** match {
    case s: String => tokenize(s)
    case b: Array[Byte] => tokenize(b)
    case other =>
      throw new IllegalArgumentException(s"StringTokenizer expected String or Array[Byte], got: ${other.getClass}")
  }
}

final class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  private def formatFloating(d: Double): String = {
    val fmt = s"%.${precision}f"
    String.format(Locale.ROOT, fmt, java.lang.Double.valueOf(d))
  }

  private def formatDecimal(d: BigDecimal): String =
    d.setScale(precision, RoundingMode.HALF_UP).bigDecimal.toPlainString

  override def tokenize(value: Any): Token = ***REDACTED***
    val (strValue, originalType) = value match {
      case bd: BigDecimal => (formatDecimal(bd), "Decimal")
      case bd: java.math.BigDecimal => (formatDecimal(BigDecimal(bd)), "Decimal")
      case d: Double => (formatFloating(d), "float")
      case f: Float => (formatFloating(f.toDouble), "float")
      case i: Int => (i.toString, "int")
      case l: Long => (l.toString, "int")
      case s: Short => (s.toString, "int")
      case b: Byte => (b.toString, "int")
      case bi: BigInt => (bi.toString, "int")
      case other =>
        throw new IllegalArgumentException(s"NumericTokenizer expected numeric type, got: ${other.getClass}")
    }

    Token(
      value = strValue,
      tokenType = TokenType.NUMERIC,
      metadata = Map("original_type" -> originalType) ++ formatOptions
    )
  }
}

object TemporalTokenizer {
  // Keep the Python strftime patterns to preserve intent.
  val ISO_FORMAT: String = "%Y-%m-%dT%H:%M:%S"
  val DATE_FORMAT: String = "%Y-%m-%d"

  private val pythonToJava: Map[String, String] = Map(
    "%Y" -> "yyyy",
    "%m" -> "MM",
    "%d" -> "dd",
    "%H" -> "HH",
    "%M" -> "mm",
    "%S" -> "ss"
  )

  def pythonStrftimeToJava(pattern: String): String = {
    // Minimal converter for the directives used in this module.
    // If you need more directives, extend pythonToJava.
    val out = new StringBuilder
    var i = 0
    while (i < pattern.length) {
      if (pattern.charAt(i) == '%' && i + 1 < pattern.length) {
        val directive = pattern.substring(i, i + 2)
        pythonToJava.get(directive) match {
          case Some(java) => out.append(java); i += 2
          case None => throw new IllegalArgumentException(s"Unsupported strftime directive: $directive")
        }
      } else {
        out.append(pattern.charAt(i))
        i += 1
      }
    }
    out.toString
  }
}

final class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  import TemporalTokenizer._

  def this(formatStr: String) = this(Option(formatStr))

  private def formatterFor(value: Any): DateTimeFormatter = {
    val pythonPattern = formatStr.getOrElse {
      value match {
        case _: LocalDateTime | _: ZonedDateTime | _: Instant => ISO_FORMAT
        case _: LocalDate => DATE_FORMAT
        case _ => DATE_FORMAT
      }
    }

    DateTimeFormatter.ofPattern(pythonStrftimeToJava(pythonPattern))
  }

  override def tokenize(value: Any): Token = ***REDACTED***
    val fmt = formatterFor(value)

    val rendered = value match {
      case dt: LocalDateTime => dt.format(fmt)
      case d: LocalDate => d.format(fmt)
      case zdt: ZonedDateTime => zdt.toLocalDateTime.format(fmt)
      case i: Instant => LocalDateTime.ofInstant(i, ZoneOffset.UTC).format(fmt)
      case other =>
        throw new IllegalArgumentException(s"TemporalTokenizer expected LocalDate/LocalDateTime/ZonedDateTime/Instant, got: ${other.getClass}")
    }

    Token(rendered, TokenType.TEMPORAL)
  }
}

final class UniversalTokenizer(
  private val stringTokenizer: StringTokenizer = new StringTokenizer(),
  private val numericTokenizer: NumericTokenizer = new NumericTokenizer(),
  private val temporalTokenizer: TemporalTokenizer = new TemporalTokenizer()
) extends Serializable {

  def tokenize(value: Any): Token = ***REDACTED*** match {
    case null => Token("NULL", TokenType.NULL)
    case None => Token("NULL", TokenType.NULL)
    case Some(v) => tokenize(v)

    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)

    case s: String => stringTokenizer.tokenize(s)
    case b: Array[Byte] => stringTokenizer.tokenize(b)

    case _: Int | _: Long | _: Short | _: Byte | _: BigInt | _: Float | _: Double | _: BigDecimal | _: java.math.BigDecimal =>
      numericTokenizer.tokenize(value)

    case _: LocalDate | _: LocalDateTime | _: ZonedDateTime | _: Instant =>
      temporalTokenizer.tokenize(value)

    case other =>
      Token(other.toString, TokenType.STRING, metadata = Map("fallback" -> true))
  }
}

