final class MutableTokenBatch extends Serializable {
  private val tokensBuffer: mutable.ListBuffer[Token] = mutable.ListBuffer.empty
  private var processed: Boolean = false

  def tokens: List[Token] = tokensBuffer.toList

  def add(token: ***REDACTED*** Unit = {
    if (processed) throw new IllegalStateException("Batch already processed")
    tokensBuffer += token
  }

  def markProcessed(): Unit = processed = true
}

// ============================================================================
// Token registry (nested generics + handlers)
// ============================================================================

final class TokenRegistry[T] extends Serializable {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit =
    registry.update(key, container)

  def addHandler(handler: T => Option[Token]): Unit =
    handlers += handler

  def process(key: String): List[Option[Token]] =
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.toList.map { item =>
          handlers.iterator
            .map(_(item))
            .collectFirst { case Some(t) => t }
        }
    }
}

