final case class TokenFunctor[+A](value: Option[A]) extends Serializable {
  def map[B](f: A => B): TokenFunctor[B] = TokenFunctor(value.map(f))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] =
    TokenFunctor(value.flatMap(a => f(a).value))

  def getOrElse[B >: A](default: => B): B = value.getOrElse(default)
}

object TokenFunctor {
  def apply[A](value: A): TokenFunctor[A] = TokenFunctor(Option(value))
}

final case class TokenMonad[+A](override val value: Option[A]) extends Serializable {
  def map[B](f: A => B): TokenMonad[B] = TokenMonad(value.map(f))

  def flatMap[B](f: A => TokenMonad[B]): TokenMonad[B] =
    TokenMonad(value.flatMap(a => f(a).value))

  def getOrElse[B >: A](default: => B): B = value.getOrElse(default)

  def ap[B](fWrapped: TokenMonad[A => B]): TokenMonad[B] =
    TokenMonad(for {
      a <- value
      f <- fWrapped.value
    } yield f(a))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = TokenMonad(Option(value))

  def apply[A](value: A): TokenMonad[A] = TokenMonad(Option(value))
}

// ============================================================================
// JSON structure tokenization (a small, dependency-free ADT)
// ============================================================================

sealed trait JsonValue extends Product with Serializable

object JsonValue {
  case object Null extends JsonValue
  final case class Str(value: String) extends JsonValue
  final case class Num(value: BigDecimal) extends JsonValue
  final case class Bool(value: Boolean) extends JsonValue
  final case class Arr(value: Vector[JsonValue]) extends JsonValue
  final case class Obj(value: Map[String, JsonValue]) extends JsonValue

  def fromAny(value: Any): Option[JsonValue] = value match {
    case null => Some(Null)
    case None => Some(Null)
    case Some(v) => fromAny(v)

    case s: String => Some(Str(s))
    case b: Boolean => Some(Bool(b))
    case i: Int => Some(Num(BigDecimal(i)))
    case l: Long => Some(Num(BigDecimal(l)))
    case d: Double => Some(Num(BigDecimal(d)))
    case f: Float => Some(Num(BigDecimal(f.toDouble)))
    case bd: BigDecimal => Some(Num(bd))
    case bd: java.math.BigDecimal => Some(Num(BigDecimal(bd)))

    case xs: Seq[_] =>
      val converted = xs.iterator.map(fromAny).toVector
      if (converted.forall(_.isDefined)) Some(Arr(converted.flatten)) else None

    case m: Map[_, _] =>
      val kvs = m.iterator.collect { case (k: String, v) => k -> fromAny(v) }.toVector
      if (kvs.forall(_._2.isDefined)) Some(Obj(kvs.map { case (k, ov) => k -> ov.get }.toMap))
      else None

    case _ => None
  }
}

final class JsonTokenizer(pretty: Boolean = false) extends Serializable {
  import JsonValue._

  private def escape(s: String): String =
    s.flatMap {
      case '"' => "\\\""
      case '\\' => "\\\\"
      case '\b' => "\\b"
      case '\f' => "\\f"
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case c if c.isControl => f"\\u${c.toInt}%04x"
      case c => c.toString
    }

  private def render(value: JsonValue, level: Int): String = {
    val indent = if (pretty) "  " * level else ""
    val newline = if (pretty) "\n" else ""
    val sep = if (pretty) ": " else ":"

    value match {
      case Null => "null"
      case Str(s) => s"\"${escape(s)}\""
      case Num(n) => n.bigDecimal.toPlainString
      case Bool(b) => if (b) "true" else "false"

      case Arr(items) =>
        if (items.isEmpty) "[]"
        else {
          val inner = items.map(v => s"${if (pretty) indent + "  " else ""}${render(v, level + 1)}")
          val joined = inner.mkString("," + newline)
          s"[${newline}${joined}${newline}${indent}]"
        }

      case Obj(fields) =>
        if (fields.isEmpty) "{}"
        else {
          val inner = fields.toVector.sortBy(_._1).map { case (k, v) =>
            val kvIndent = if (pretty) indent + "  " else ""
            s"${kvIndent}\"${escape(k)}\"$sep${render(v, level + 1)}"
          }
          val joined = inner.mkString("," + newline)
          s"{${newline}${joined}${newline}${indent}}"
        }
    }
  }

  def tokenize(value: JsonValue): Token =
    Token(render(value, 0), TokenType.STRUCTURED, metadata = Map("json" -> true))

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList.filter(_.nonEmpty)

    @tailrec
    def loop(current: JsonValue, remaining: List[String]): Option[JsonValue] = remaining match {
      case Nil => Some(current)
      case part :: tail =>
        current match {
          case Obj(fields) => fields.get(part).flatMap(loop(_, tail))
          case Arr(items) if part.forall(_.isDigit) =>
            val idx = part.toInt
            items.lift(idx).flatMap(loop(_, tail))
          case _ => None
        }
    }

    loop(value, parts).map(tokenize)
  }
}

// ============================================================================
// Whitespace tokenizer
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) extends Serializable {

  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def stripEdgePunctuation(word: String): String = {
    def dropLeading(s: String): String = s.dropWhile(punctuation.contains)
    def dropTrailing(s: String): String = s.reverse.dropWhile(punctuation.contains).reverse
    dropTrailing(dropLeading(word))
  }

  private def processToken(word0: String): Option[String] = {
    val word1 = if (stripPunctuation) stripEdgePunctuation(word0) else word0
    val word2 = if (lowercase) word1.toLowerCase(Locale.ROOT) else word1

    if (word2.length < minLength) None
    else {
      val trimmed = maxLength match {
        case Some(m) if word2.length > m => word2.take(m)
        case _ => word2
      }
      Option(trimmed).filter(_.nonEmpty)
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)

    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)

    @tailrec
    def loop(remaining: List[String], currentPos: Int, acc: List[(String, Int, Int)]): List[(String, Int, Int)] =
      remaining match {
        case Nil => acc.reverse
        case word :: tail =>
          val start = text.indexOf(word, currentPos)
          val end = if (start >= 0) start + word.length else currentPos

          val nextAcc = processToken(word) match {
            case Some(processed) if start >= 0 => (processed, start, end) :: acc
            case _ => acc
          }

          loop(tail, end, nextAcc)
      }

    loop(words, 0, Nil)
  }

  def countTokens(text: String): Int = tokenize(text).length
}

