final case class TokenizerValidationError(message: String) extends RuntimeException(message)

final class TokenizerBuilder[T] extends Serializable {
  private var normalizers: Vector[String => String] = Vector.empty
  private var validators: Vector[T => Boolean] = Vector.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(kvs: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kvs.toMap
    this
  }

  def build(): T => Token = ***REDACTED***
    val ns = normalizers
    val vs = validators
    val md = metadata

    (value: T) => {
      vs.foreach { v =>
        if (!v(value)) throw TokenizerValidationError(s"Validation failed for $value")
      }

      val normalized = ns.foldLeft(value.toString) { case (acc, n) => n(acc) }
      Token(normalized, TokenType.STRING, md)
    }
  }
}

